"""Models and textures of the Final Castle completion: the Rune Sovereign, the Forge Harbinger and the rune ward.

  python make_models.py <TF source checkout>

One description per model (parts, pivots, boxes, a paint style per box) gives both:
  * the Java of the model's LayerDefinition, printed between "// ---- generated by make_models.py" markers into
    the model classes (client/model/entity/*Model.java), so geometry and texture can never drift apart;
  * the texture and its emissive ("glow") twin under textures/entity/.

Everything is drawn here, pixel by pixel, from TF's palette (white castle stone, violet runes, gold; charred iron and
molten seams); no other art is used. Seeded noise, so every run gives the same files. Shared under CC BY-NC-SA 4.0
like the rest of TF's art.
"""
import math
import random
import re
import sys
from pathlib import Path

from PIL import Image

TEX = "src/main/resources/assets/twilightforest/textures/entity"
JAVA = "src/main/java/twilightforest/client/model/entity"

# ---------------------------------------------------------------------------------------------------------------- palette
WHITE = (232, 228, 238)
WHITE_SHADE = (196, 190, 210)
WHITE_DEEP = (160, 152, 178)
VIOLET = (123, 63, 209)
VIOLET_DARK = (58, 29, 110)
VIOLET_GLOW = (214, 150, 255)
GOLD = (214, 172, 70)
GOLD_DARK = (150, 110, 40)
GOLD_LIGHT = (246, 216, 120)
SHADOW = (18, 10, 28)
GLOVE = (48, 32, 62)
WOOD = (59, 36, 72)
IRON = (62, 46, 42)
IRON_DARK = (34, 25, 23)
IRON_LIGHT = (98, 78, 70)
EMBER = (255, 150, 40)
EMBER_HOT = (255, 226, 120)
EMBER_DIM = (190, 70, 20)

# 5x5 rune glyphs drawn for this pack (not letters of any script)
GLYPHS = [
    ["..#..", ".###.", "#.#.#", "..#..", ".#.#."],
    ["#...#", ".#.#.", "..#..", ".#.#.", "#...#"],
    ["###..", "..#..", "..###", "....#", "..###"],
    [".###.", "#...#", "#.#.#", "#...#", ".###."],
    ["#.#.#", "#.#.#", "#####", "..#..", "..#.."],
    ["..#..", "..#..", "#####", ".#.#.", "#...#"],
]


def shade(c, k):
    return tuple(max(0, min(255, int(v * k))) for v in c)


class Canvas:
    def __init__(self, w, h, seed):
        self.base = Image.new("RGBA", (w, h), (0, 0, 0, 0))
        self.glow = Image.new("RGBA", (w, h), (0, 0, 0, 0))
        self.rnd = random.Random(seed)

    def put(self, x, y, c, glow=None):
        self.base.putpixel((x, y), c + (255,) if len(c) == 3 else c)
        if glow:
            self.glow.putpixel((x, y), glow + (255,) if len(glow) == 3 else glow)


# ---------------------------------------------------------------------------------------------------------------- painting
def glyph(canvas, ox, oy, fw, fh, index, colour, glow=None, at=None):
    g = GLYPHS[index % len(GLYPHS)]
    gx, gy = at if at else ((fw - 5) // 2, (fh - 5) // 2)
    for j, row in enumerate(g):
        for i, ch in enumerate(row):
            if ch == "#" and 0 <= gx + i < fw and 0 <= gy + j < fh:
                canvas.put(ox + gx + i, oy + gy + j, colour, glow)


def paint_face(canvas, style, face, ox, oy, fw, fh, n):
    """Paint one face (fw x fh pixels at ox, oy). n: the box's number, for variety."""
    r = canvas.rnd
    for y in range(fh):
        for x in range(fw):
            canvas.put(ox + x, oy + y, STYLES[style](r, face, x, y, fw, fh))
    # decorations on top of the base
    deco = DECOR.get(style)
    if deco:
        deco(canvas, face, ox, oy, fw, fh, n)


def cloth(r, face, x, y, fw, fh):
    if face == "down":
        return shade(WHITE_DEEP, r.uniform(0.95, 1.03))
    if face == "up":
        return shade(WHITE, r.uniform(0.97, 1.02))
    side = 0.93 if face in ("east", "west") else 1.0           # sides a step darker than the front
    fold = 0.9 if (x % 4 == 1) else 1.03 if (x % 4 == 2) else 1.0   # vertical folds: a crease and a lit ridge
    fall = 1.0 - 0.12 * (y / max(1, fh - 1))                    # darker towards the ground
    return shade(WHITE, r.uniform(0.97, 1.02) * side * fold * fall)


def cloth_trim(r, face, x, y, fw, fh):
    if face in ("north", "south", "east", "west") and y >= fh - 2:
        return shade(VIOLET, r.uniform(0.9, 1.05))
    if face in ("north", "south", "east", "west") and y == fh - 3:
        return shade(GOLD, r.uniform(0.9, 1.05))
    return cloth(r, face, x, y, fw, fh)


def gold(r, face, x, y, fw, fh):
    edge = x == 0 or y == 0 or x == fw - 1 or y == fh - 1
    if face == "up":
        return shade(GOLD_LIGHT if not edge else GOLD, r.uniform(0.93, 1.03))
    return shade(GOLD_DARK if edge else GOLD, r.uniform(0.92, 1.04))


def glove(r, face, x, y, fw, fh):
    return shade(GLOVE, r.uniform(0.9, 1.1))


def wood(r, face, x, y, fw, fh):
    if y % 7 == 0 and face not in ("up", "down"):
        return shade(GOLD, r.uniform(0.9, 1.05))
    return shade(WOOD, r.uniform(0.85, 1.1))


def crystal(r, face, x, y, fw, fh):
    t = y / max(1, fh - 1)
    return tuple(int(VIOLET_GLOW[i] * (1 - t) + VIOLET[i] * t) for i in range(3))


def cape(r, face, x, y, fw, fh):
    if face in ("north", "south") and (x == 0 or x == fw - 1):
        return shade(GOLD, r.uniform(0.9, 1.05))
    if face in ("north", "south") and y >= fh - 2:
        return shade(GOLD, r.uniform(0.9, 1.05))
    return shade(VIOLET_DARK, r.uniform(0.9, 1.1))


def hood(r, face, x, y, fw, fh):
    if face == "north":
        rim = x == 0 or x == fw - 1 or y == 0 or y >= fh - 1
        if not rim and y >= 2:
            return shade(SHADOW, r.uniform(0.8, 1.2))
    return cloth(r, face, x, y, fw, fh)


def rune_cube(r, face, x, y, fw, fh):
    return shade(VIOLET, r.uniform(0.85, 1.05))


def iron(r, face, x, y, fw, fh):
    k = r.uniform(0.86, 1.1)
    if x == 0 or y == 0 or x == fw - 1 or y == fh - 1:
        return shade(IRON_LIGHT, k * 0.95)
    if x % 7 == 0 or y % 7 == 0:                               # grooves between the panels
        return shade(IRON_DARK, k)
    px, py = x % 7, y % 7
    light = 1.18 if (px == 1 or py == 1) else 0.9 if (px == 6 or py == 6) else 1.0
    return shade(IRON, k * light)


def iron_dark(r, face, x, y, fw, fh):
    return shade(IRON_DARK, r.uniform(0.8, 1.2))


def anvil(r, face, x, y, fw, fh):
    if face == "up":
        k = r.uniform(0.85, 1.1) * (0.85 if (x * 7 + y * 3) % 11 == 0 else 1.0)   # hammer marks
        return shade(IRON_LIGHT, k)
    return iron(r, face, x, y, fw, fh)


def ward_frame(r, face, x, y, fw, fh):
    return shade(GOLD, r.uniform(0.85, 1.05))


def ward_core(r, face, x, y, fw, fh):
    return shade(VIOLET_DARK, r.uniform(0.9, 1.1))


STYLES = {"cloth": cloth, "cloth_trim": cloth_trim, "gold": gold, "glove": glove, "wood": wood, "crystal": crystal,
          "cape": cape, "hood": hood, "rune_cube": rune_cube, "iron": iron, "iron_dark": iron_dark, "anvil": anvil,
          "plate": iron, "grate": iron_dark, "chimney": iron, "leg": iron, "ward_frame": ward_frame, "ward_core": ward_core,
          "torso": cloth, "hem": cloth_trim, "belt": gold, "body": iron, "vents": iron}


# ---- decorations (drawn after the base: runes, rivets, seams, eyes) ----
def deco_torso(c, face, ox, oy, fw, fh, n):
    if face == "north":
        for x in range(fw):                       # gold collar
            c.put(ox + x, oy, GOLD)
        glyph(c, ox, oy, fw, fh, 0, VIOLET, VIOLET_GLOW, at=((fw - 5) // 2, 3))
        for y in range(2, fh):                    # the robe's violet seam down the middle
            if y > 8:
                c.put(ox + fw // 2, oy + y, VIOLET, None)
    if face == "south":
        glyph(c, ox, oy, fw, fh, 3, VIOLET_DARK)


def deco_hem(c, face, ox, oy, fw, fh, n):
    if face in ("north", "south", "east", "west"):
        k = 0
        for gx in range(1, fw - 5, 7):
            glyph(c, ox, oy, fw, fh, n + k, VIOLET, VIOLET_GLOW if face == "north" else None, at=(gx, max(0, fh - 9)))
            k += 1


def deco_hood(c, face, ox, oy, fw, fh, n):
    if face == "north":
        ey = fh // 2
        for ex in (fw // 2 - 3, fw // 2 + 1):
            for i in range(2):
                c.put(ox + ex + i, oy + ey, VIOLET_GLOW, (255, 200, 255))
    if face in ("east", "west", "south"):
        for y in range(fh):
            c.put(ox + (fw - 1 if face == "east" else 0), oy + y, WHITE_DEEP)


def deco_gold(c, face, ox, oy, fw, fh, n):
    if face in ("north", "up") and fw >= 5 and fh >= 5:
        glyph(c, ox, oy, fw, fh, n + 2, GOLD_DARK)


def deco_belt(c, face, ox, oy, fw, fh, n):
    if face == "north":
        cx = fw // 2
        for dx in (-1, 0):
            for dy in range(fh):
                c.put(ox + cx + dx, oy + dy, VIOLET_GLOW, VIOLET_GLOW)


def deco_crystal(c, face, ox, oy, fw, fh, n):
    for y in range(fh):
        for x in range(fw):
            r, g, b, a = c.base.getpixel((ox + x, oy + y))
            c.glow.putpixel((ox + x, oy + y), (r, g, b, 255))


def deco_rune_cube(c, face, ox, oy, fw, fh, n):
    """A violet stone with a dark rim and a glowing heart."""
    for y in range(fh):
        for x in range(fw):
            rim = x == 0 or y == 0 or x == fw - 1 or y == fh - 1
            c.put(ox + x, oy + y, VIOLET_DARK if rim else VIOLET)
    c.put(ox + fw // 2, oy + fh // 2, VIOLET_GLOW, VIOLET_GLOW)


def deco_cape(c, face, ox, oy, fw, fh, n):
    if face in ("north", "south"):
        for k, gy in enumerate(range(3, fh - 7, 8)):
            glyph(c, ox, oy, fw, fh, k + 1, GOLD_DARK, at=((fw - 5) // 2, gy))


def deco_vents(c, face, ox, oy, fw, fh, n):
    deco_plate(c, face, ox, oy, fw, fh, n)
    if face in ("east", "west", "north", "south") and fw >= 10 and fh >= 8:
        for k in range(3):                         # three glowing vents
            vy = 3 + k * 3
            for x in range(3, fw - 3):
                col = EMBER if (x + k) % 5 else EMBER_HOT
                c.put(ox + x, oy + vy, col, col)


def deco_plate(c, face, ox, oy, fw, fh, n):
    if face in ("north", "south", "east", "west"):
        for (x, y) in ((1, 1), (fw - 2, 1), (1, fh - 2), (fw - 2, fh - 2)):   # rivets
            c.put(ox + x, oy + y, IRON_LIGHT)
            if x + 1 < fw:
                c.put(ox + x + 1, oy + y, IRON_DARK)


def deco_iron(c, face, ox, oy, fw, fh, n):
    """Molten cracks: runs of the panel grooves glow, with a dim red halo on the iron around them."""
    if face in ("up", "down"):
        return
    rnd = random.Random(n * 31 + len(face))
    cracks = []
    for gy in range(7, fh - 1, 7):                 # horizontal grooves
        start = rnd.randrange(0, max(1, fw - 6))
        cracks += [(x, gy) for x in range(start, min(fw - 1, start + rnd.randrange(5, 14)))]
    for gx in range(7, fw - 1, 7):                 # vertical grooves
        if rnd.random() < 0.6:
            start = rnd.randrange(0, max(1, fh - 4))
            cracks += [(gx, y) for y in range(start, min(fh - 1, start + rnd.randrange(3, 9)))]
    crack = set(cracks)
    for (x, y) in crack:
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            hx, hy = x + dx, y + dy
            if 0 < hx < fw - 1 and 0 < hy < fh - 1 and (hx, hy) not in crack:
                c.put(ox + hx, oy + hy, EMBER_DIM, (110, 30, 5))
    for (x, y) in crack:
        hot = rnd.random() < 0.35
        col = EMBER_HOT if hot else EMBER
        c.put(ox + x, oy + y, col, col)
    deco_plate(c, face, ox, oy, fw, fh, n)


def deco_grate(c, face, ox, oy, fw, fh, n):
    """The forge's mouth: dark bars over a glowing fire."""
    if face != "north":
        return
    for y in range(fh):
        for x in range(fw):
            bar = x % 4 == 0 or y == 0 or y == fh - 1 or x == fw - 1 or y == fh // 3
            if bar:
                c.put(ox + x, oy + y, IRON_DARK)
            else:
                heat = 1.0 - abs(y - fh * 0.7) / (fh * 0.8) - abs(x - fw / 2) / (fw * 1.6)
                heat += c.rnd.uniform(-0.12, 0.12)
                col = EMBER_HOT if heat > 0.82 else EMBER if heat > 0.5 else EMBER_DIM if heat > 0.2 else (110, 30, 12)
                c.put(ox + x, oy + y, col, col)


def deco_leg(c, face, ox, oy, fw, fh, n):
    if face in ("north", "south", "east", "west"):
        for x in range(fw):                       # an armour band round the knee
            c.put(ox + x, oy + 2, IRON_LIGHT)
            c.put(ox + x, oy + 3, shade(IRON_LIGHT, 0.8))
        for x in range(fw):
            c.put(ox + x, oy + fh - 1, IRON_DARK)
            c.put(ox + x, oy + fh - 2, shade(IRON_DARK, 1.3))
        if face == "north":
            for x in range(1, fw - 1, 2):     # claws
                c.put(ox + x, oy + fh - 1, (120, 110, 100))


def deco_chimney(c, face, ox, oy, fw, fh, n):
    if face == "up":
        for y in range(1, fh - 1):
            for x in range(1, fw - 1):
                c.put(ox + x, oy + y, EMBER, EMBER)


def deco_ward_frame(c, face, ox, oy, fw, fh, n):
    pass


def deco_ward_core(c, face, ox, oy, fw, fh, n):
    glyph(c, ox, oy, fw, fh, n, VIOLET_GLOW, VIOLET_GLOW)


def deco_body(c, face, ox, oy, fw, fh, n):
    deco_iron(c, face, ox, oy, fw, fh, n)
    if face == "north":
        # two slit eyes above the forge mouth
        for ex in (fw // 2 - 6, fw // 2 + 3):
            for i in range(3):
                c.put(ox + ex + i, oy + 3, EMBER_HOT, EMBER_HOT)
                c.put(ox + ex + i, oy + 4, EMBER, EMBER)


DECOR = {"body": deco_body, "vents": deco_vents, "torso": deco_torso, "hem": deco_hem, "hood": deco_hood, "gold": deco_gold, "belt": deco_belt,
         "crystal": deco_crystal, "rune_cube": deco_rune_cube, "cape": deco_cape, "plate": deco_plate,
         "iron": deco_iron, "grate": deco_grate, "leg": deco_leg, "chimney": deco_chimney, "anvil": deco_plate,
         "ward_frame": deco_ward_frame, "ward_core": deco_ward_core}


# ---------------------------------------------------------------------------------------------------------------- layout
def box(style, x, y, z, w, h, d, mirror=False):
    return {"style": style, "pos": (x, y, z), "size": (w, h, d), "mirror": mirror}


def part(name, parent, pivot, boxes, rot=(0, 0, 0)):
    return {"name": name, "parent": parent, "pivot": pivot, "boxes": boxes, "rot": rot}


def pack(parts, tex_w):
    """Shelf-pack every box's UV rectangle (2d+2w by d+h) into the texture."""
    items = []
    for p in parts:
        for b in p["boxes"]:
            w, h, d = (math.ceil(v) for v in b["size"])
            items.append((b, 2 * d + 2 * w, d + h))
    items.sort(key=lambda t: -t[2])
    x = y = shelf = 0
    for b, iw, ih in items:
        if x + iw > tex_w:
            x, y, shelf = 0, y + shelf, 0
        b["uv"] = (x, y)
        x += iw
        shelf = max(shelf, ih)
    return y + shelf


def faces(b):
    """The six faces of a box in its UV rectangle (vanilla ModelPart.Cube layout)."""
    u, v = b["uv"]
    w, h, d = (math.ceil(s) for s in b["size"])
    return {"down": (u + d + w, v, w, d), "up": (u + d, v, w, d),
            "east": (u, v + d, d, h), "north": (u + d, v + d, w, h),
            "west": (u + d + w, v + d, d, h), "south": (u + d + w + d, v + d, w, h)}


def render(model, tex_w, tex_h, seed, root):
    parts = model["parts"]
    used = pack(parts, tex_w)
    if used > tex_h:
        sys.exit(f"{model['texture']}: needs {used} rows of texture, has {tex_h}")
    canvas = Canvas(tex_w, tex_h, seed)
    n = 0
    for p in parts:
        for b in p["boxes"]:
            for face, (fx, fy, fw, fh) in faces(b).items():
                paint_face(canvas, b["style"], face, fx, fy, fw, fh, n)
            n += 1
    out = root / TEX
    canvas.base.save(out / model["texture"])
    preview(model, canvas, parts)
    canvas.glow.save(out / model["texture"].replace(".png", "_glow.png"))

    def f(v):
        return f"{float(v)}F"

    lines = ["		MeshDefinition mesh = new MeshDefinition();", "		PartDefinition root = mesh.getRoot();"]
    for p in parts:
        cubes = "CubeListBuilder.create()"
        for b in p["boxes"]:
            (x, y, z), (w, h, d) = b["pos"], b["size"]
            cubes += f"\n				.texOffs({b['uv'][0]}, {b['uv'][1]})" + (".mirror()" if b["mirror"] else "") + \
                     f".addBox({f(x)}, {f(y)}, {f(z)}, {f(w)}, {f(h)}, {f(d)})"
        px, py, pz = p["pivot"]
        rx, ry, rz = p["rot"]
        pose = f"PartPose.offsetAndRotation({f(px)}, {f(py)}, {f(pz)}, {f(rx)}, {f(ry)}, {f(rz)})" if any(p["rot"]) else f"PartPose.offset({f(px)}, {f(py)}, {f(pz)})"
        parent = "root" if p["parent"] is None else p["parent"]
        lines.append(f"		PartDefinition {p['name']} = {parent}.addOrReplaceChild(\"{p['name']}\", {cubes},\n			{pose});")
    lines.append(f"		return LayerDefinition.create(mesh, {tex_w}, {tex_h});")
    java = root / JAVA / model["java"]
    src = java.read_text(encoding="utf-8")
    start, end = "		// ---- generated by make_models.py\n", "		// ---- end of generated\n"
    a, b = src.index(start) + len(start), src.index(end)
    java.write_text(src[:a] + "\n".join(lines) + "\n" + src[b:], encoding="utf-8", newline="\n")
    print(f"{model['texture']}: {sum(len(p['boxes']) for p in parts)} boxes, {used}/{tex_h} rows; {model['java']} updated")


def preview(model, canvas, parts, scale=6):
    """Front (north) and right-hand side views of the model at rest, with the glow added, for a quick look."""
    pivots = {}
    for p in parts:
        base = pivots[p["parent"]] if p["parent"] else (0, 0, 0)
        pivots[p["name"]] = tuple(base[i] + p["pivot"][i] for i in range(3))
    views = []
    for view in ("north", "east"):
        img = Image.new("RGBA", (64, 64), (24, 30, 40, 255))
        boxes = []
        for p in parts:
            px, py, pz = pivots[p["name"]]
            for b in p["boxes"]:
                (x, y, z), (w, h, d) = b["pos"], b["size"]
                boxes.append((b, px + x, py + y, pz + z, w, h, d))
        # far boxes first
        boxes.sort(key=lambda t: -(t[3]) if view == "north" else (t[1] + t[4]))
        for b, x, y, z, w, h, d in boxes:
            fx, fy, fw, fh = faces(b)[view]
            for j in range(fh):
                for i in range(fw):
                    col = canvas.base.getpixel((fx + i, fy + j))
                    glow = canvas.glow.getpixel((fx + i, fy + j))
                    if glow[3]:
                        col = tuple(min(255, col[k] + glow[k] // 2) for k in range(3)) + (255,)
                    sx = int((x if view == "north" else z) + 32 + i)
                    sy = int(y + 34 + j)
                    if 0 <= sx < 64 and 0 <= sy < 64 and col[3]:
                        img.putpixel((sx, sy), col)
        views.append(img)
    sheet = Image.new("RGBA", (128 + 4, 64), (0, 0, 0, 255))
    sheet.paste(views[0], (0, 0))
    sheet.paste(views[1], (68, 0))
    sheet.resize((sheet.width * scale, sheet.height * scale), Image.NEAREST).save(PREVIEW / model["texture"].replace(".png", "_preview.png"))


PREVIEW = Path(".")


# ---------------------------------------------------------------------------------------------------------------- models
def sovereign():
    halo = []
    for i in range(8):
        a = i * math.pi / 4
        halo.append(box("rune_cube", round(math.cos(a) * 9 - 1.5, 2), -1.5, round(math.sin(a) * 9 - 1.5, 2), 3, 3, 3))
    return {"texture": "rune_sovereign.png", "java": "RuneSovereignModel.java", "parts": [
        part("body", None, (0, 0, 0), [box("torso", -6, -14, -3.5, 12, 12, 7), box("belt", -6.5, -3, -4, 13, 2, 8),
                                       box("gold", -7, -15, -4.5, 14, 2, 9)]),
        part("skirt", "body", (0, -2, 0), [box("cloth", -7, 0, -4.5, 14, 10, 9)]),
        part("hem", "skirt", (0, 10, 0), [box("hem", -8, 0, -5, 16, 9, 10)]),
        part("cape", "body", (0, -14, 3.5), [box("cape", -6, 0, 0, 12, 29, 1)]),
        part("head", "body", (0, -14, 0), [box("hood", -5, -11, -5, 10, 11, 10), box("cloth", -2, -13, -1, 4, 3, 6),
                                           box("cloth_trim", -5.5, -11.5, -6, 11, 3, 2)]),
        part("halo", "head", (0, -15, 0), halo),
        part("right_arm", "body", (-7, -12, 0), [box("gold", -4, -2.5, -4, 6, 4, 8), box("cloth_trim", -3.5, 1, -2.5, 5, 12, 5),
                                                   box("glove", -2.5, 13, -1.5, 3, 3, 3)]),
        part("staff", "right_arm", (-1, 14.5, 0), [box("wood", -1, -20, -1, 2, 30, 2), box("gold", -1.5, -21, -1.5, 3, 1, 3),
                                                     box("crystal", -2, -26, -2, 4, 5, 4), box("gold", -1.5, 10, -1.5, 3, 1, 3)]),
        part("left_arm", "body", (7, -12, 0), [box("gold", -2, -2.5, -4, 6, 4, 8, True), box("cloth_trim", -1.5, 1, -2.5, 5, 12, 5, True),
                                                 box("glove", -0.5, 13, -1.5, 3, 3, 3, True)]),
    ]}


def harbinger():
    legs = []
    for name, x, z in (("leg_front_right", -9, -9), ("leg_front_left", 9, -9), ("leg_back_right", -9, 9), ("leg_back_left", 9, 9)):
        legs.append(part(name, None, (x, 16, z), [box("leg", -4, 0, -4, 8, 8, 8)]))
    return {"texture": "forge_harbinger.png", "java": "ForgeHarbingerModel.java", "parts": [
        part("body", None, (0, 16, 0), [box("body", -13, -20, -13, 26, 20, 26)]),
        part("mouth", "body", (0, -9, -13), [box("grate", -10, -7, -1, 20, 11, 1)]),
        part("plates", "body", (0, 0, 0), [box("vents", -14, -17, -9, 1, 12, 18), box("vents", 13, -17, -9, 1, 12, 18, True),
                                           box("plate", -9, -17, 13, 18, 12, 1)]),
        part("anvil", "body", (0, -20, 0), [box("anvil", -14, -3, -14, 28, 3, 28)]),
        part("chimney", "anvil", (6, -3, 7), [box("chimney", -3, -4, -3, 6, 4, 6)]),
        part("horn", "anvil", (-8, -3, 8), [box("iron_dark", -2, -3, -2, 4, 3, 4)]),
    ] + legs}


def ward():
    frame = []
    s, t = 5, 1   # half size, bar thickness
    for x in (-s, s - t):
        for z in (-s, s - t):
            frame.append(box("ward_frame", x, -s, z, t, 2 * s, t))
    for y in (-s, s - t):
        for z in (-s, s - t):
            frame.append(box("ward_frame", -s + t, y, z, 2 * s - 2 * t, t, t))
        for x in (-s, s - t):
            frame.append(box("ward_frame", x, y, -s + t, t, t, 2 * s - 2 * t))
    return {"texture": "rune_ward.png", "java": "RuneWardModel.java", "parts": [
        part("frame", None, (0, 17, 0), frame),
        part("core", None, (0, 17, 0), [box("ward_core", -3, -3, -3, 6, 6, 6)]),
    ]}


def main():
    global PREVIEW
    root = Path(sys.argv[1])
    if len(sys.argv) > 2:
        PREVIEW = Path(sys.argv[2])
    render(sovereign(), 128, 128, 115, root)
    render(harbinger(), 256, 128, 2016, root)
    render(ward(), 64, 64, 7, root)


if __name__ == "__main__":
    main()
